scan_linter_check.script:
(function(engine) {
    var context = new global.EcsContext(engine.current);
    if (!engine.rootNode || context.clientKind() !== 'client' || context.value('type') !== 'onChange') {
        return;
    }
    var hits = new global.EcsClientScript(new global.EcsAst(engine.rootNode), 'client').onChangeGuards();
    var report = new global.EcsReport(engine, {
        ruleId: 'SN-CLIENT-002',
        title: 'onChange client script without a load/empty guard',
        recommendation: 'Start the function with the standard guard: if (isLoading || newValue === \'\') { return; } ' +
            'Without it the script also runs when the form loads and when the field is cleared, which causes ' +
            'unneeded server calls and overwrites values.'
    });
    for (var i = 0; i < hits.length; i++) {
        report.add(hits[i].node, hits[i].message);
    }
    report.flush();
})(engine);
